using System;using System.Buffers.Binary;using System.IO;using Cocoa.Build;using Xunit;namespace Cocoa.Tests.Projects{    public class SubsystemPEEmitTests : IDisposable    {        private readonly string _directory;        private readonly StringWriter _out = new();        public SubsystemPEEmitTests()        {            _directory = Path.Combine(Path.GetTempPath(), "cocoa_subsys_" + Guid.NewGuid().ToString("N"));            Directory.CreateDirectory(_directory);            File.WriteAllText(Path.Combine(_directory, "main.co"),                "using System\n\nfunction Main()\n{\n    Console.WriteLine(\"ok\")\n}\n");        }        public void Dispose()        {            _out.Dispose();            try            {                Directory.Delete(_directory, recursive: true);            }            catch (IOException)            {            }        }        private CocoaProjectFile WriteProject(string subsystemLine)        {            var xml =                "<Project Version=\"1\">\n" +                "  <PropertyGroup Label=\"Language\"><Language>Cocoa</Language></PropertyGroup>\n" +                "  <PropertyGroup Label=\"Assembly\"><AssemblyName>App</AssemblyName></PropertyGroup>\n" +                "  <PropertyGroup Label=\"Target\"><Platform>x64</Platform></PropertyGroup>\n" +                "  <PropertyGroup Label=\"Output\"><OutputType>Executable</OutputType>" + subsystemLine + "</PropertyGroup>\n" +                "  <PropertyGroup Label=\"Build\"><OutputPath>out</OutputPath></PropertyGroup>\n" +                "  <ItemGroup><Source Include=\"*.co\" /></ItemGroup>\n" +                "</Project>\n";            var path = Path.Combine(_directory, "App.coproj");            File.WriteAllText(path, xml);            return CocoaProjectFile.Load(path);        }        private static ushort ReadSubsystem(string exePath)        {            var bytes = File.ReadAllBytes(exePath);            var ntOffset = BinaryPrimitives.ReadInt32LittleEndian(bytes.AsSpan(0x3C, 4));            var optionalHeader = ntOffset + 24;            var magic = BinaryPrimitives.ReadUInt16LittleEndian(bytes.AsSpan(optionalHeader, 2));            Assert.True(magic is 0x10B or 0x20B, $"unexpected PE optional header magic 0x{magic:X4}");            return BinaryPrimitives.ReadUInt16LittleEndian(bytes.AsSpan(optionalHeader + 68, 2));        }        [Fact]        public void Subsystem_Windows_EmitsWindowsGui()        {            var project = WriteProject("<Subsystem>Windows</Subsystem>");            var result = ProjectBuilder.Build(                project,                new ProjectBuildOptions { CacheRoot = _directory, Backend = Cocoa.Targeting.CodeBackend.Native },                _out);            Assert.True(result.Success, _out.ToString());            Assert.Equal(2, ReadSubsystem(Path.Combine(_directory, "out", "App.exe")));        }        [Fact]        public void Subsystem_Default_IsConsole()        {            var project = WriteProject("");            var result = ProjectBuilder.Build(                project,                new ProjectBuildOptions { CacheRoot = _directory, Backend = Cocoa.Targeting.CodeBackend.Native },                _out);            Assert.True(result.Success, _out.ToString());            Assert.Equal(3, ReadSubsystem(Path.Combine(_directory, "out", "App.exe")));        }    }}